pages['404']=('صفحه پیدا نشد','''<div class="container empty-state page-space"><span class="error-code">۴۰۴</span><h1>این مسیر به هشتگ نمی‌رسد.</h1><p>شاید نشانی تغییر کرده باشد. از فروشگاه شروع کنیم؟</p><a class="button dark" href="shop.html">بازگشت به فروشگاه <svg class="inline-arrow" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 12H4m6-6-6 6 6 6"/></svg></a></div>''')
