for key,(title,body) in pages.items():
 module='shop' if key in ['shop','category','search'] else 'home' if key=='index' else 'product' if key=='product' else 'pages'
 html=f'''<!DOCTYPE html>
<html lang="fa" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="موبایل هشتگ؛ فروشگاه نمایشی گوشی هوشمند، لوازم جانبی و گجت با تجربه خرید فارسی."><meta name="theme-color" content="#c9a44c"><title>{title} | موبایل هشتگ</title><link rel="icon" href="/favicon.png" type="image/png"><link rel="preload" href="/assets/fonts/vazirmatn-arabic-400.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/css/style.css"><script type="module" src="/assets/js/{module}.js"></script></head><body data-page="{key}"><a class="skip-link" href="#main">رفتن به محتوای اصلی</a><header id="site-header"></header><main id="main">{body}</main><footer id="site-footer"></footer><div id="toast-region" aria-live="polite" aria-atomic="true"></div><dialog id="app-dialog"></dialog><noscript><p>برای استفاده از امکانات فروشگاه، جاوااسکریپت مرورگر را فعال کنید.</p></noscript></body></html>'''
 Path(f'frontend/{key}.html').write_text(html)
print(f'{len(pages)} separate HTML pages created.')
